/* ── animador mínimo ──────────────────────────────────────────────────────
   Reproduce los fotogramas que trae cada icono con la Web Animations API:
     · cada propiedad animada (y, x, scaleY, rotate, opacity...) se convierte en
       una animación independiente con «composite: add», que es exactamente cómo
       el original compone los movimientos;
     · los orígenes de transformación por nodo salen del propio dato;
     · si el sistema pide menos movimiento, el icono se queda quieto.
   El icono se pinta como texto (innerHTML) para no cargar el hilo; los datos de
   cada nodo se vuelven a enlazar al dibujarlo, así el juego pesa sólo lo que
   ocupan sus fotogramas.
   ───────────────────────────────────────────────────────────────────────── */

function aniMenosMovimiento() {
  try { return window.matchMedia("(prefers-reduced-motion: reduce)").matches; } catch (e) { return false; }
}

/** Traduce la clave de propiedad del icono a una propiedad CSS. */
function aniPropiedad(clave, valor) {
  if (clave === "opacity") return { prop: "opacity", css: String(valor) };
  if (clave === "x" || clave === "y" || clave === "translateX" || clave === "translateY") {
    var eje = clave === "x" || clave === "translateX" ? "X" : "Y";
    return { prop: "transform", css: "translate" + eje + "(" + valor + "px)" };
  }
  if (clave === "scale" || clave === "scaleX" || clave === "scaleY" || clave === "scaleZ") {
    return { prop: "transform", css: clave === "scale" ? "scale(" + valor + ")" : clave + "(" + valor + ")" };
  }
  if (clave === "rotate") return { prop: "transform", css: "rotate(" + valor + "deg)" };
  return null;
}

/* Los nombres de curva del juego original («motion») a curvas estándar. */
var ANI_EASE = {
  linear: "linear",
  easeIn: "cubic-bezier(0.42,0,1,1)",
  easeOut: "cubic-bezier(0,0,0.58,1)",
  easeInOut: "cubic-bezier(0.42,0,0.58,1)",
  circIn: "cubic-bezier(0.55,0,1,0.45)",
  circOut: "cubic-bezier(0,0.55,0.45,1)",
  backOut: "cubic-bezier(0.34,1.56,0.64,1)"
};
function aniEase(v, i) {
  if (Array.isArray(v)) return ANI_EASE[v[Math.min(i, v.length - 1)]] || "ease-in-out";
  return ANI_EASE[v] || "ease-in-out";
}

var ANI_NS = "http://www.w3.org/2000/svg";

/** Construye un nodo del icono con sus atributos, origen e hijos. */
function aniNodo(nodo) {
  var el = document.createElementNS(ANI_NS, nodo.tag);
  Object.keys(nodo.attrs || {}).forEach(function (k) { el.setAttribute(k, nodo.attrs[k]); });
  var st = nodo.style || {};
  if (st.originX != null || st.originY != null) {
    el.style.transformBox = st.transformBox || "view-box";
    el.style.transformOrigin = (st.originX != null ? st.originX : "0") + " " +
      (st.originY != null ? st.originY : "0");
  }
  (nodo.children || []).forEach(function (hijo) { el.appendChild(aniNodo(hijo)); });
  return el;
}

/** Enlaza los datos de cada nodo con el SVG ya dibujado (mismo orden). */
function aniAtar(svg) {
  // Se lee el atributo, no `dataset`: así también funciona en WebViews donde
  // `dataset` no existe sobre elementos SVG.
  var nombre = svg.getAttribute ? svg.getAttribute("data-ani") : "";
  var d = ANI_ICONOS[nombre || ""];
  if (!d) return false;
  (function caminar(datos, padre) {
    datos.forEach(function (nodo, i) {
      var hijo = padre.children && padre.children[i];
      if (!hijo) return;
      hijo._ani = nodo;
      caminar(nodo.children || [], hijo);
    });
  })(d.children || [], svg);
  svg._aniDatos = d;
  return true;
}

/** Lanza la animación de todos los nodos que traigan fotogramas. */
function aniReproducir(svg, duracion) {
  if (!svg._aniDatos && !aniAtar(svg)) return;
  var escala = duracion || 1;
  var nodos = [svg].concat(Array.prototype.slice.call(svg.querySelectorAll("*")));
  nodos.forEach(function (el) {
    var nodo = el._ani;
    if (!nodo || !nodo.animate) return;
    Object.keys(nodo.animate).forEach(function (clave) {
      if (clave === "transition") return;
      var vals = nodo.animate[clave];
      var tr = (nodo.animate.transition || {})[clave] || nodo.animate.transition || {};
      if (typeof tr !== "object" || Array.isArray(tr)) tr = {};
      if (!Array.isArray(vals)) vals = [vals];
      var primero = aniPropiedad(clave, vals[0]);
      if (!primero) return;
      var veces = tr.times || null;
      var kf = vals.map(function (v, k) {
        var p = aniPropiedad(clave, v);
        var paso = { offset: veces && veces[k] != null ? veces[k] : k / Math.max(1, vals.length - 1) };
        paso[p.prop] = p.css;
        paso.easing = aniEase(tr.ease, k);
        return paso;
      });
      try {
        el.animate(kf, {
          duration: (tr.duration || 0.6) * 1000 * escala,
          delay: (tr.delay || 0) * 1000,
          composite: primero.prop === "transform" ? "add" : "replace",
          fill: "none"
        });
      } catch (e) { /* un icono sin animación no puede romper la pantalla */ }
    });
  });
}

/**
 * Icono animado en línea. `nombre` es la clave del icono; `tam` el lado en px;
 * `opts.clase` añade una clase CSS extra.
 */
function aniIcono(nombre, tam, opts) {
  var d = ANI_ICONOS[nombre];
  if (!d) return "";
  var o = opts || {};
  var t = tam || 24;
  var attrs = Object.keys(d.attrs || {}).map(function (k) {
    return k + '="' + String(d.attrs[k]).replace(/"/g, "&quot;") + '"';
  }).join(" ");
  var cuerpo = d.children.map(function (c) { return aniNodo(c).outerHTML; }).join("");
  return '<svg class="ani' + (o.clase ? " " + o.clase : "") + '" ' + attrs +
    ' width="' + t + '" height="' + t + '" aria-hidden="true" data-ani="' + nombre + '">' +
    cuerpo + "</svg>";
}

var ANI_VISTOS = [];

/** Engancha los iconos ya pintados: anima al tocar/pasar y, si se pide, solo. */
function aniEnganchar(raiz, opts) {
  var o = opts || {};
  var quieto = aniMenosMovimiento();
  Array.prototype.slice.call((raiz || document).querySelectorAll("svg[data-ani]")).forEach(function (svg) {
    if (svg.getAttribute && svg.getAttribute("data-ani-listo") === "1") return;
    if (svg.setAttribute) svg.setAttribute("data-ani-listo", "1");
    svg._disparar = function () { aniReproducir(svg, o.duracion); };
    var cont = svg.closest("[data-ani-hover]") || svg;
    cont.addEventListener("pointerenter", svg._disparar);
    cont.addEventListener("click", svg._disparar);
    if (quieto) return;
    if (o.solo) {
      ANI_VISTOS.push(svg);
      svg._disparar();
    }
  });
}

/* Los iconos «solo» se repiten cada cierto tiempo, pero únicamente los que
   están a la vista: fuera de pantalla no se anima nada (el teléfono lo agradece). */
if (!window.ANI_TIMER) {
  window.ANI_TIMER = setInterval(function () {
    var alto = window.innerHeight || 800;
    ANI_VISTOS.forEach(function (svg) {
      if (!document.body.contains(svg)) return;
      var r = svg.getBoundingClientRect();
      if (r.top < alto && r.bottom > 0 && svg._disparar) svg._disparar();
    });
  }, 5200);
}
